"""Localized labels for the project workspace and local research controls.

The first field is the stable label key. Values follow en, de, fr, es, it, pt,
nl. Markers such as ``research/`` and ``{count}`` are interface data, not
translated. The dashboard escapes text for its HTML context when rendering.
"""

