        "Analyse grammaticale : {groups} groupes verbaux ; {excluded} hors du périmètre ; {other} autres formes ; {unresolved} non résolus. Subjonctif et futur sont exclus des comptages. Des erreurs restent possibles ; les citations ne désignent pas les locuteurs.",
        "Análisis gramatical: {groups} grupos verbales; {excluded} fuera del ámbito; {other} otras formas; {unresolved} sin resolver. Subjuntivo y futuro no entran en estos recuentos. Puede haber errores; las citas no identifican al hablante.",
        "Analisi grammaticale: {groups} gruppi verbali; {excluded} fuori ambito; {other} altre forme; {unresolved} irrisolti. Congiuntivo e futuro non entrano nei conteggi. Sono possibili errori; le citazioni non identificano chi parla.",
        "Análise gramatical: {groups} grupos verbais; {excluded} fora do âmbito; {other} outras formas; {unresolved} por resolver. Conjuntivo e futuro não entram nas contagens. Podem ocorrer erros; as citações não identificam quem fala.",
        "Grammaticale analyse: {groups} werkwoordgroepen; {excluded} buiten het telbereik; {other} andere vormen; {unresolved} onopgelost. Aanvoegende wijs en toekomst tellen niet mee. Parserfouten blijven mogelijk; citaten wijzen geen spreker aan.",
